export default function formatProductData(productNode) {
  if (!productNode) {
    return null;
  }

  const featuredImage
    = productNode?.media?.edges?.[0]?.node?.image || productNode?.featuredImage || null;
  const variants = (productNode?.variants?.edges || []).map((edge) => {
    const v = edge.node || {};
    const selectedOptions = (v.selectedOptions || []).map((o) => ({
      name: o.name,
      value: o.value,
    }));

    const optionsMap = {};
    selectedOptions.forEach((o) => {
      optionsMap[o.name] = o.value;
    });

    return {
      id: v.id,
      title: v.title || '',
      price: v.price?.amount ? Number(v.price.amount) : null,
      comparePrice: v.compareAtPrice?.amount ? Number(v.compareAtPrice?.amount) : null,
      currency: v.price?.currencyCode || null,
      selectedOptions,
      options: optionsMap,
    };
  });

  const numericPrices = variants
    .map((v) => (v.price === null ? null : Number(v.price)))
    .filter((p) => p !== null && !Number.isNaN(p));

  const fallbackMin = productNode?.priceRange?.minVariantPrice?.amount
    ? Number(productNode.priceRange.minVariantPrice.amount)
    : null;

  const fallbackMax = productNode?.priceRange?.maxVariantPrice?.amount
    ? Number(productNode.priceRange.maxVariantPrice.amount)
    : null;

  let minPrice = null;
  let maxPrice = null;

  if (numericPrices.length) {
    minPrice = Math.min(...numericPrices);
    maxPrice = Math.max(...numericPrices);
  } else if (fallbackMin !== null) {
    minPrice = fallbackMin;
    maxPrice = fallbackMax;
  }

  const currency
    = variants[0]?.currency
    || productNode?.priceRange?.minVariantPrice?.currencyCode
    || null;

  return {
    id: productNode.id,
    title: productNode.title,
    handle: productNode.handle,
    availableForSale: productNode.availableForSale,
    description: productNode.descriptionHtml,
    image: featuredImage?.url || null,
    featuredImage: featuredImage
      ? {
        url: featuredImage.url,
        altText: featuredImage.altText,
        width: featuredImage.width,
        height: featuredImage.height,
      }
      : null,
    variants,
    minPrice,
    maxPrice,
    currency,
    comparePrice: productNode.comparePrice,
  };
}
