import { PRODUCT_QUERY } from './product-queries';

export const COLLECTION_PRODUCTS_QUERY = `query GetCollectionWithProducts(
  $handle: String!
  $first: Int
  $after: String
  $last: Int
  $before: String
  $filters: [ProductFilter!],
  $sortKey: ProductCollectionSortKeys!,
  $reverse: Boolean!,
  $country: CountryCode
  $language: LanguageCode
) @inContext(country: $country, language: $language) {
  collection(handle: $handle) {
    id
    title
    products(first: $first, after: $after, last: $last, before: $before, sortKey: $sortKey, reverse: $reverse, filters: $filters) {
      pageInfo {
        hasNextPage
        hasPreviousPage
        startCursor
        endCursor
      }
      filters {
        id
        label
        type
        values {
          id
          label
          count
          input
          swatch {
            color
          }
        }
      }

      nodes {
        ...productQuery
      }
    }
  }
}
${PRODUCT_QUERY}`;

